  cmd: "git fetch origin && python3 - <<'PY'
import subprocess
from pathlib import Path

root = Path('/Users/kenneth/.codex/worktrees/e4f4/JusPrin')
raw = subprocess.check_output(['git', '-C', str(root), 'worktree', 'list', '--porcelain'], text=True)
records=[]
cur={}
for line in raw.splitlines()+['']:
    if not line:
        if cur: records.append(cur); cur={}
        continue
    key, _, val = line.partition(' ')
    cur[key]=val

problems=[]
for rec in records:
    path=Path(rec['worktree'])
    print(f'WORKTREE {path}')
    if not path.exists():
        print('  MISSING')
        problems.append((str(path),'missing worktree'))
        continue
    status=subprocess.run(['git','-C',str(path),'status','--porcelain=v1','--untracked-files=all'],text=True,capture_output=True)
    lines=status.stdout.splitlines()
    if lines:
        print(f'  DIRTY {len(lines)} entries')
        for item in lines[:20]: print('   ',item)
        if len(lines)>20: print(f'    ... {len(lines)-20} more')
        problems.append((str(path),f'dirty ({len(lines)} entries)'))
    else:
        print('  CLEAN')
    branch=subprocess.run(['git','-C',str(path),'symbolic-ref','--quiet','--short','HEAD'],text=True,capture_output=True)
    if branch.returncode:
        print('  DETACHED')
        continue
    name=branch.stdout.strip()
    upstream=subprocess.run(['git','-C',str(path),'rev-parse','--abbrev-ref','--symbolic-full-name','@{upstream}'],text=True,capture_output=True)
    if upstream.returncode:
        print(f'  BRANCH {name} NO_UPSTREAM')
        problems.append((str(path),f'{name} has no upstream'))
        continue
    up=upstream.stdout.strip()
    counts=subprocess.check_output(['git','-C',str(path),'rev-list','--left-right','--count',f'{up}...HEAD'],text=True).strip().split()
    behind,ahead=map(int,counts)
    print(f'  BRANCH {name} UPSTREAM {up} BEHIND {behind} AHEAD {ahead}')
    if ahead:
        problems.append((str(path),f'{name} has {ahead} unpushed commits'))

print('SUMMARY')
if problems:
    for path,msg in problems: print(f'  BLOCKER {path}: {msg}')
else:
    print('  ALL_REGISTERED_WORKTREES_CLEAN_AND_PUSHED')
